function dump(name, v)
	local t = type(v)
	if t == "table" then
		local names = ""
		local k, x = next(v, nil)
		while k ~= nil do
			names = names .. tostring(k) .. "(" .. type(x) .. ") "
			k, x = next(v, k)
		end
		out[name] = "table: " .. names
	else
		out[name] = t
	end
end
